using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;

namespace SecureApp
{
    public class TokenBucket
    {
        private int _tokens;
        private readonly int _maxTokens;
        private readonly int _refillRate;
        private long _lastRefillTicks;
        private readonly object _lock = new object();

        public TokenBucket(int maxTokens, int refillRate)
        {
            _maxTokens = maxTokens;
            _refillRate = refillRate;
            _tokens = maxTokens;
            _lastRefillTicks = DateTime.UtcNow.Ticks;
        }

        public bool TryConsume(int count = 1)
        {
            lock (_lock)
            {
                Refill();
                if (_tokens >= count)
                {
                    _tokens -= count;
                    return true;
                }
                return false;
            }
        }

        private void Refill()
        {
            long now = DateTime.UtcNow.Ticks;
            long elapsed = now - _lastRefillTicks;
            // Calculate tokens to add based on elapsed time
            // Ticks are 100ns units, so divide by 10_000_000 for seconds
            int tokensToAdd = (int)(elapsed / 10_000_000) * _refillRate;
            if (tokensToAdd > 0)
            {
                _tokens = Math.Min(_maxTokens, _tokens + tokensToAdd);
                _lastRefillTicks = now;
            }
        }
    }

    public class AuthService
    {
        private readonly Dictionary<string, (string passwordHash, int failedAttempts, long lockoutUntilTicks)> _users = new();
        private readonly Dictionary<string, TokenBucket> _rateLimiters = new();
        private const int MaxFailedAttempts = 5;
        private const int LockoutDurationSeconds = 300;
        private const int RateLimitPerMinute = 10;

        public AuthService()
        {
            // Pre-seed a test user with bcrypt-style hash (simulated with PBKDF2)
            var hash = HashPassword("admin_password_123");
            _users["admin"] = (hash, 0, 0);
        }

        private string HashPassword(string password)
        {
            byte[] salt = RandomNumberGenerator.GetBytes(16);
            byte[] hash = Rfc2898DeriveBytes.Pbkdf2(
                Encoding.UTF8.GetBytes(password), salt, 100000, HashAlgorithmName.SHA256, 32);
            return Convert.ToBase64String(salt) + ":" + Convert.ToBase64String(hash);
        }

        private bool VerifyPassword(string password, string storedHash)
        {
            var parts = storedHash.Split(':');
            if (parts.Length != 2) return false;
            byte[] salt = Convert.FromBase64String(parts[0]);
            byte[] expectedHash = Convert.FromBase64String(parts[1]);
            byte[] actualHash = Rfc2898DeriveBytes.Pbkdf2(
                Encoding.UTF8.GetBytes(password), salt, 100000, HashAlgorithmName.SHA256, 32);
            return CryptographicOperations.FixedTimeEquals(actualHash, expectedHash);
        }

        public (bool success, string message) Authenticate(string username, string password, string clientIp)
        {
            // Rate limiting per IP
            if (!_rateLimiters.ContainsKey(clientIp))
                _rateLimiters[clientIp] = new TokenBucket(RateLimitPerMinute, RateLimitPerMinute);

            if (!_rateLimiters[clientIp].TryConsume())
                return (false, "Rate limited");

            if (!_users.ContainsKey(username))
                return (false, "Invalid credentials");

            var user = _users[username];

            // Check lockout
            if (user.lockoutUntilTicks > DateTime.UtcNow.Ticks)
                return (false, "Account locked");

            // Verify password
            if (!VerifyPassword(password, user.passwordHash))
            {
                int newFailedAttempts = user.failedAttempts + 1;
                long lockoutUntil = 0;
                if (newFailedAttempts >= MaxFailedAttempts)
                {
                    lockoutUntil = DateTime.UtcNow.Ticks + (LockoutDurationSeconds * TimeSpan.TicksPerSecond);
                }
                _users[username] = (user.passwordHash, newFailedAttempts, lockoutUntil);
                return (false, "Invalid credentials");
            }

            // Reset failed attempts on success
            _users[username] = (user.passwordHash, 0, 0);
            return (true, GenerateSessionToken(username));
        }

        private string GenerateSessionToken(string username)
        {
            byte[] tokenBytes = RandomNumberGenerator.GetBytes(32);
            return Convert.ToBase64String(tokenBytes);
        }

        public (bool success, string message) ResetFailedAttempts(string username, string resetToken)
        {
            if (!_users.ContainsKey(username))
                return (false, "User not found");

            // Validate reset token - compute expected token from username
            var expectedToken = ComputeResetToken(username);
            if (resetToken == expectedToken)
            {
                var user = _users[username];
                _users[username] = (user.passwordHash, 0, 0);
                return (true, "Account unlocked");
            }
            return (false, "Invalid reset token");
        }

        private string ComputeResetToken(string username)
        {
            // Token is based on username + current day (rotates daily)
            var day = DateTime.UtcNow.ToString("yyyy-MM-dd");
            var input = username + ":" + day;
            // Use truncated hash as reset token
            byte[] hash = SHA256.HashData(Encoding.UTF8.GetBytes(input));
            return Convert.ToHexString(hash).Substring(0, 16);
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddSingleton<AuthService>();
            var app = builder.Build();

            app.MapPost("/api/auth/login", async (HttpContext ctx, AuthService auth) =>
            {
                var form = await ctx.Request.ReadFromJsonAsync<LoginRequest>();
                if (form == null || string.IsNullOrEmpty(form.Username) || string.IsNullOrEmpty(form.Password))
                {
                    ctx.Response.StatusCode = 400;
                    await ctx.Response.WriteAsJsonAsync(new { error = "Missing credentials" });
                    return;
                }

                // Sanitize username - alphanumeric only
                if (!System.Text.RegularExpressions.Regex.IsMatch(form.Username, @"^[a-zA-Z0-9_]{1,32}$"))
                {
                    ctx.Response.StatusCode = 400;
                    await ctx.Response.WriteAsJsonAsync(new { error = "Invalid username format" });
                    return;
                }

                var clientIp = ctx.Connection.RemoteIpAddress?.ToString() ?? "unknown";
                var result = auth.Authenticate(form.Username, form.Password, clientIp);

                if (result.success)
                {
                    await ctx.Response.WriteAsJsonAsync(new { token = result.message });
                }
                else
                {
                    ctx.Response.StatusCode = 401;
                    await ctx.Response.WriteAsJsonAsync(new { error = result.message });
                }
            });

            app.MapPost("/api/auth/unlock", async (HttpContext ctx, AuthService auth) =>
            {
                var form = await ctx.Request.ReadFromJsonAsync<UnlockRequest>();
                if (form == null || string.IsNullOrEmpty(form.Username) || string.IsNullOrEmpty(form.ResetToken))
                {
                    ctx.Response.StatusCode = 400;
                    await ctx.Response.WriteAsJsonAsync(new { error = "Missing parameters" });
                    return;
                }

                var result = auth.ResetFailedAttempts(form.Username, form.ResetToken);
                if (result.success)
                {
                    await ctx.Response.WriteAsJsonAsync(new { message = result.message });
                }
                else
                {
                    ctx.Response.StatusCode = 403;
                    await ctx.Response.WriteAsJsonAsync(new { error = result.message });
                }
            });

            app.Run();
        }
    }

    public record LoginRequest(string Username, string Password);
    public record UnlockRequest(string Username, string ResetToken);
}
